-- 20261025e_kien_thuc_phap_ly — Kho kiến thức pháp lý / thủ tục nhà đất bot được phép trả lời (SRS-5.1zzzzzzz176, 25/10/2026; chủ dự án: "Nạp sẵn đi
-- nạp vào luôn, tôi ko biết duyệt"). SINH TỰ ĐỘNG bởi scripts/sinh-migration-phap-ly.py từ src/aioi/phap_ly.MAC_DINH — đừng sửa tay nội dung ở
-- đây; sửa ở phap_ly.py rồi sinh lại, hoặc admin sửa cột tra_loi trên DB (lõi đọc đè, nhớ 60 giây). Dòng chưa ai sửa (tra_loi = mac_dinh)
-- chuyển sang câu mới; dòng đã sửa tay giữ nguyên. Nội dung do AI soạn theo luật, CHƯA người có chuyên môn duyệt (kiem_duyet = 'chua').
create table if not exists public.kien_thuc_phap_ly (
  khoa text primary key,
  tieu_de text not null,
  tra_loi text not null,
  mac_dinh text not null,
  nguon text,
  nhom text,
  cap_nhat date not null default current_date,
  kiem_duyet text not null default 'chua',
  thu_tu integer not null default 0,
  updated_at timestamptz not null default now()
);
comment on table public.kien_thuc_phap_ly is '[BOT & HÀNG ĐỢI] Kho kiến thức pháp lý / thủ tục nhà đất bot được phép trả lời (SRS-5.1zzzzzzz176). AI chọn khoá theo nghĩa câu khách, lõi đọc tra_loi (đè câu mặc định trong src/aioi/phap_ly.py, nhớ 60 giây) và luôn nói "tham khảo". Khoá cố định trong code; admin chỉ sửa tra_loi / cap_nhat / kiem_duyet. Chỉ admin.';
comment on column public.kien_thuc_phap_ly.tra_loi is 'Câu bot dùng (admin sửa được). Bằng mac_dinh nghĩa là chưa ai sửa.';
comment on column public.kien_thuc_phap_ly.mac_dinh is 'Câu mặc định từ code — để biết dòng đã sửa tay hay chưa.';
comment on column public.kien_thuc_phap_ly.cap_nhat is 'Ngày nội dung được soạn / kiểm — bot nói "theo bản em có cập nhật tháng X".';
comment on column public.kien_thuc_phap_ly.kiem_duyet is 'chua = AI soạn, chưa người có chuyên môn duyệt; ghi tên người duyệt + ngày khi đã duyệt.';
alter table public.kien_thuc_phap_ly enable row level security;
revoke all on public.kien_thuc_phap_ly from anon, authenticated;
grant select, update on public.kien_thuc_phap_ly to authenticated;
drop policy if exists kien_thuc_phap_ly_admin_doc on public.kien_thuc_phap_ly;
create policy kien_thuc_phap_ly_admin_doc on public.kien_thuc_phap_ly for select to authenticated using (public.la_admin());
drop policy if exists kien_thuc_phap_ly_admin_sua on public.kien_thuc_phap_ly;
create policy kien_thuc_phap_ly_admin_sua on public.kien_thuc_phap_ly for update to authenticated using (public.la_admin()) with check (public.la_admin());

insert into public.kien_thuc_phap_ly (khoa, tieu_de, tra_loi, mac_dinh, nguon, nhom, cap_nhat, kiem_duyet, thu_tu) values
  ('so_do_so_hong', 'Sổ đỏ, sổ hồng khác gì nhau; sổ cũ còn giá trị không', 'Sổ đỏ hay sổ hồng chỉ là tên gọi theo màu bìa của các mẫu Giấy chứng nhận qua từng thời kỳ; về pháp lý đều là Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất. Từ 01/01/2025 có mẫu giấy mới theo Luật Đất đai 2024, nhưng sổ cũ đã cấp vẫn có giá trị, không bắt buộc đổi; chỉ đổi khi có biến động hoặc chủ sổ muốn.', 'Sổ đỏ hay sổ hồng chỉ là tên gọi theo màu bìa của các mẫu Giấy chứng nhận qua từng thời kỳ; về pháp lý đều là Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất. Từ 01/01/2025 có mẫu giấy mới theo Luật Đất đai 2024, nhưng sổ cũ đã cấp vẫn có giá trị, không bắt buộc đổi; chỉ đổi khi có biến động hoặc chủ sổ muốn.', 'Luật Đất đai 2024 (Điều 256); Thông tư 10/2024/TT-BTNMT về mẫu Giấy chứng nhận', 'giay_to', '2026-10-25', 'chua', 1),
  ('thue_phi_sang_ten', 'Mua bán nhà đất phải nộp những thuế phí gì, bên nào chịu', 'Một giao dịch mua bán thường có: thuế thu nhập cá nhân của bên bán (2% giá chuyển nhượng), lệ phí trước bạ của bên mua (0,5%), phí công chứng hợp đồng (tính theo giá trị, thường vài triệu), và lệ phí cấp sổ, phí thẩm định hồ sơ (vài trăm nghìn tới hơn một triệu tuỳ địa phương). Luật không bắt buộc bên nào chịu khoản nào ngoài nghĩa vụ thuế của từng bên, nên hai bên thoả thuận và ghi rõ trong hợp đồng đặt cọc; thực tế hay gặp là bên bán chịu thuế thu nhập cá nhân, bên mua chịu trước bạ và phí công chứng.', 'Một giao dịch mua bán thường có: thuế thu nhập cá nhân của bên bán (2% giá chuyển nhượng), lệ phí trước bạ của bên mua (0,5%), phí công chứng hợp đồng (tính theo giá trị, thường vài triệu), và lệ phí cấp sổ, phí thẩm định hồ sơ (vài trăm nghìn tới hơn một triệu tuỳ địa phương). Luật không bắt buộc bên nào chịu khoản nào ngoài nghĩa vụ thuế của từng bên, nên hai bên thoả thuận và ghi rõ trong hợp đồng đặt cọc; thực tế hay gặp là bên bán chịu thuế thu nhập cá nhân, bên mua chịu trước bạ và phí công chứng.', 'Luật Thuế thu nhập cá nhân; Nghị định 10/2022/NĐ-CP về lệ phí trước bạ; Thông tư 257/2016/TT-BTC về phí công chứng', 'thue_phi', '2026-10-25', 'chua', 2),
  ('thue_tncn', 'Thuế thu nhập cá nhân khi bán nhà đất, trường hợp được miễn', 'Bên bán nộp thuế thu nhập cá nhân 2% trên giá chuyển nhượng ghi trong hợp đồng (nếu giá hợp đồng thấp hơn bảng giá đất của Nhà nước thì tính theo bảng giá). Được miễn trong vài trường hợp chính: bán nhà đất duy nhất (chỉ sở hữu một bất động sản, đã có quyền tối thiểu 183 ngày và bán toàn bộ), hoặc chuyển nhượng giữa vợ chồng, cha mẹ với con, ông bà với cháu, anh chị em ruột. Cách tính thuế có thể thay đổi theo luật thuế mới, nên kiểm lại với chi cục thuế trước khi ký.', 'Bên bán nộp thuế thu nhập cá nhân 2% trên giá chuyển nhượng ghi trong hợp đồng (nếu giá hợp đồng thấp hơn bảng giá đất của Nhà nước thì tính theo bảng giá). Được miễn trong vài trường hợp chính: bán nhà đất duy nhất (chỉ sở hữu một bất động sản, đã có quyền tối thiểu 183 ngày và bán toàn bộ), hoặc chuyển nhượng giữa vợ chồng, cha mẹ với con, ông bà với cháu, anh chị em ruột. Cách tính thuế có thể thay đổi theo luật thuế mới, nên kiểm lại với chi cục thuế trước khi ký.', 'Luật Thuế thu nhập cá nhân (Điều 4, Điều 14); Thông tư 111/2013/TT-BTC', 'thue_phi', '2026-10-25', 'chua', 3),
  ('le_phi_truoc_ba', 'Lệ phí trước bạ nhà đất là bao nhiêu', 'Lệ phí trước bạ nhà đất là 0,5% giá tính lệ phí (giá ghi trong hợp đồng, nếu thấp hơn giá Nhà nước thì tính theo giá Nhà nước), do bên nhận chuyển nhượng nộp khi đăng ký sang tên. Một số trường hợp được miễn như nhận thừa kế, tặng cho giữa vợ chồng, cha mẹ và con, ông bà và cháu, anh chị em ruột.', 'Lệ phí trước bạ nhà đất là 0,5% giá tính lệ phí (giá ghi trong hợp đồng, nếu thấp hơn giá Nhà nước thì tính theo giá Nhà nước), do bên nhận chuyển nhượng nộp khi đăng ký sang tên. Một số trường hợp được miễn như nhận thừa kế, tặng cho giữa vợ chồng, cha mẹ và con, ông bà và cháu, anh chị em ruột.', 'Nghị định 10/2022/NĐ-CP (Điều 8, Điều 10)', 'thue_phi', '2026-10-25', 'chua', 4),
  ('phi_cong_chung', 'Phí công chứng hợp đồng mua bán tính như thế nào', 'Phí công chứng tính theo giá trị hợp đồng theo biểu phí Nhà nước: ví dụ giao dịch từ 1 tới 3 tỷ là 1 triệu đồng cộng 0,06% phần vượt 1 tỷ; từ 3 tới 5 tỷ là 2,2 triệu cộng 0,05% phần vượt 3 tỷ; từ 5 tới 10 tỷ là 3,2 triệu cộng 0,04% phần vượt 5 tỷ. Ngoài phí này, văn phòng công chứng thu thêm thù lao soạn thảo, đi lại, mỗi nơi niêm yết khác nhau, nên hỏi báo giá trước. Biểu phí có thể được điều chỉnh theo Luật Công chứng 2024.', 'Phí công chứng tính theo giá trị hợp đồng theo biểu phí Nhà nước: ví dụ giao dịch từ 1 tới 3 tỷ là 1 triệu đồng cộng 0,06% phần vượt 1 tỷ; từ 3 tới 5 tỷ là 2,2 triệu cộng 0,05% phần vượt 3 tỷ; từ 5 tới 10 tỷ là 3,2 triệu cộng 0,04% phần vượt 5 tỷ. Ngoài phí này, văn phòng công chứng thu thêm thù lao soạn thảo, đi lại, mỗi nơi niêm yết khác nhau, nên hỏi báo giá trước. Biểu phí có thể được điều chỉnh theo Luật Công chứng 2024.', 'Thông tư 257/2016/TT-BTC (Điều 4); Luật Công chứng 2024 (hiệu lực 01/07/2025)', 'thue_phi', '2026-10-25', 'chua', 5),
  ('quy_trinh_mua_ban', 'Các bước mua bán nhà đất từ đặt cọc tới sang tên', 'Thứ tự thường gặp: (1) kiểm tra sổ, quy hoạch, chủ sở hữu và tình trạng thế chấp; (2) ký hợp đồng đặt cọc, nên ghi rõ giá, thời hạn, bên chịu thuế phí; (3) ký hợp đồng chuyển nhượng tại văn phòng công chứng nơi có bất động sản, thanh toán phần lớn tiền; (4) nộp thuế thu nhập cá nhân và lệ phí trước bạ; (5) nộp hồ sơ đăng ký biến động tại Văn phòng đăng ký đất đai hoặc bộ phận một cửa để sang tên; (6) nhận sổ đã cập nhật tên mới, thanh toán phần còn lại, bàn giao nhà.', 'Thứ tự thường gặp: (1) kiểm tra sổ, quy hoạch, chủ sở hữu và tình trạng thế chấp; (2) ký hợp đồng đặt cọc, nên ghi rõ giá, thời hạn, bên chịu thuế phí; (3) ký hợp đồng chuyển nhượng tại văn phòng công chứng nơi có bất động sản, thanh toán phần lớn tiền; (4) nộp thuế thu nhập cá nhân và lệ phí trước bạ; (5) nộp hồ sơ đăng ký biến động tại Văn phòng đăng ký đất đai hoặc bộ phận một cửa để sang tên; (6) nhận sổ đã cập nhật tên mới, thanh toán phần còn lại, bàn giao nhà.', 'Luật Đất đai 2024 (Điều 45, Điều 133); Luật Công chứng 2024; Luật Kinh doanh bất động sản 2023', 'thu_tuc', '2026-10-25', 'chua', 6),
  ('ho_so_ban_nha', 'Người bán cần chuẩn bị giấy tờ gì để công chứng', 'Thường cần: bản chính Giấy chứng nhận (sổ hồng / sổ đỏ); căn cước của người đứng tên và vợ hoặc chồng; giấy đăng ký kết hôn, hoặc giấy xác nhận tình trạng hôn nhân nếu độc thân, hoặc giấy tờ chứng minh tài sản riêng; nếu nhờ người khác ký thì cần hợp đồng uỷ quyền công chứng. Nhà có nhiều đồng sở hữu thì tất cả phải ký hoặc uỷ quyền. Văn phòng công chứng sẽ báo thêm giấy tờ theo từng hồ sơ.', 'Thường cần: bản chính Giấy chứng nhận (sổ hồng / sổ đỏ); căn cước của người đứng tên và vợ hoặc chồng; giấy đăng ký kết hôn, hoặc giấy xác nhận tình trạng hôn nhân nếu độc thân, hoặc giấy tờ chứng minh tài sản riêng; nếu nhờ người khác ký thì cần hợp đồng uỷ quyền công chứng. Nhà có nhiều đồng sở hữu thì tất cả phải ký hoặc uỷ quyền. Văn phòng công chứng sẽ báo thêm giấy tờ theo từng hồ sơ.', 'Luật Công chứng 2024; Luật Hôn nhân và gia đình 2014 (Điều 33, Điều 35)', 'thu_tuc', '2026-10-25', 'chua', 7),
  ('dat_coc', 'Đặt cọc bao nhiêu, bỏ cọc hoặc chủ đổi ý thì xử lý sao', 'Mức cọc do hai bên thoả thuận, thực tế hay từ vài chục triệu tới khoảng 5–10% giá bán. Theo Bộ luật Dân sự, nếu bên mua từ chối giao kết thì mất tiền cọc; nếu bên bán từ chối thì phải trả lại cọc và một khoản tiền bằng cọc, trừ khi hợp đồng thoả thuận khác. Hợp đồng đặt cọc không bắt buộc công chứng nhưng nên lập văn bản, có người làm chứng hoặc công chứng để dễ xử lý khi có tranh cãi.', 'Mức cọc do hai bên thoả thuận, thực tế hay từ vài chục triệu tới khoảng 5–10% giá bán. Theo Bộ luật Dân sự, nếu bên mua từ chối giao kết thì mất tiền cọc; nếu bên bán từ chối thì phải trả lại cọc và một khoản tiền bằng cọc, trừ khi hợp đồng thoả thuận khác. Hợp đồng đặt cọc không bắt buộc công chứng nhưng nên lập văn bản, có người làm chứng hoặc công chứng để dễ xử lý khi có tranh cãi.', 'Bộ luật Dân sự 2015 (Điều 328)', 'thu_tuc', '2026-10-25', 'chua', 8),
  ('vi_bang', 'Mua nhà bằng vi bằng thừa phát lại có an toàn không', 'Vi bằng chỉ là văn bản ghi nhận một sự kiện, hành vi (ví dụ việc giao tiền), do thừa phát lại lập; nó không phải hợp đồng công chứng và không có giá trị chuyển quyền sở hữu, nên không dùng để sang tên sổ được. Pháp luật cũng cấm lập vi bằng để ghi nhận việc chuyển nhượng nhà đất không đủ điều kiện. Mua bán qua vi bằng rủi ro cao, bên em không khuyến khích.', 'Vi bằng chỉ là văn bản ghi nhận một sự kiện, hành vi (ví dụ việc giao tiền), do thừa phát lại lập; nó không phải hợp đồng công chứng và không có giá trị chuyển quyền sở hữu, nên không dùng để sang tên sổ được. Pháp luật cũng cấm lập vi bằng để ghi nhận việc chuyển nhượng nhà đất không đủ điều kiện. Mua bán qua vi bằng rủi ro cao, bên em không khuyến khích.', 'Nghị định 08/2020/NĐ-CP (Điều 36, Điều 37)', 'giay_to', '2026-10-25', 'chua', 9),
  ('chua_hoan_cong', 'Nhà xây xong chưa hoàn công có bán được không', 'Chưa hoàn công nghĩa là phần nhà chưa được ghi nhận trên Giấy chứng nhận; sổ chỉ công nhận đất (hoặc công nhận ngôi nhà cũ). Vẫn có thể chuyển nhượng phần đã có trên sổ, nhưng bên mua không được công nhận quyền sở hữu phần nhà chưa hoàn công, khó vay ngân hàng, và nếu xây sai phép có thể bị xử lý. An toàn hơn là chủ hoàn công cập nhật tài sản lên sổ trước khi bán.', 'Chưa hoàn công nghĩa là phần nhà chưa được ghi nhận trên Giấy chứng nhận; sổ chỉ công nhận đất (hoặc công nhận ngôi nhà cũ). Vẫn có thể chuyển nhượng phần đã có trên sổ, nhưng bên mua không được công nhận quyền sở hữu phần nhà chưa hoàn công, khó vay ngân hàng, và nếu xây sai phép có thể bị xử lý. An toàn hơn là chủ hoàn công cập nhật tài sản lên sổ trước khi bán.', 'Luật Xây dựng 2014 (sửa đổi 2020); Nghị định 101/2024/NĐ-CP về đăng ký, cấp Giấy chứng nhận', 'giay_to', '2026-10-25', 'chua', 10),
  ('dat_chua_so', 'Đất chưa có sổ, mua bán giấy tay có được không', 'Điều kiện để chuyển nhượng quyền sử dụng đất là phải có Giấy chứng nhận (trừ vài trường hợp như thừa kế). Đất chưa có sổ mua bằng giấy tay thì hợp đồng không có giá trị pháp lý để sang tên, bên mua không được công nhận quyền sử dụng và rất khó đòi lại tiền khi tranh chấp. Bên em không nhận rao những tin không có giấy tờ rõ ràng.', 'Điều kiện để chuyển nhượng quyền sử dụng đất là phải có Giấy chứng nhận (trừ vài trường hợp như thừa kế). Đất chưa có sổ mua bằng giấy tay thì hợp đồng không có giá trị pháp lý để sang tên, bên mua không được công nhận quyền sử dụng và rất khó đòi lại tiền khi tranh chấp. Bên em không nhận rao những tin không có giấy tờ rõ ràng.', 'Luật Đất đai 2024 (Điều 45)', 'giay_to', '2026-10-25', 'chua', 11),
  ('tra_quy_hoach', 'Kiểm tra quy hoạch, lộ giới của một thửa đất ở đâu', 'Có vài cách: tra trên ứng dụng / cổng thông tin quy hoạch của TP.HCM theo số tờ, số thửa ghi trên sổ; hỏi trực tiếp UBND phường hoặc Văn phòng đăng ký đất đai; hoặc nộp phiếu yêu cầu cung cấp thông tin quy hoạch tại cơ quan quản lý đất đai (có phí, có văn bản trả lời). Thông tin trên ứng dụng chỉ để tham khảo, muốn chắc thì xin văn bản.', 'Có vài cách: tra trên ứng dụng / cổng thông tin quy hoạch của TP.HCM theo số tờ, số thửa ghi trên sổ; hỏi trực tiếp UBND phường hoặc Văn phòng đăng ký đất đai; hoặc nộp phiếu yêu cầu cung cấp thông tin quy hoạch tại cơ quan quản lý đất đai (có phí, có văn bản trả lời). Thông tin trên ứng dụng chỉ để tham khảo, muốn chắc thì xin văn bản.', 'Luật Quy hoạch đô thị và nông thôn 2024; Luật Đất đai 2024 (quyền tiếp cận thông tin đất đai)', 'quy_hoach', '2026-10-25', 'chua', 12),
  ('lo_gioi', 'Nhà dính lộ giới, quy hoạch đường nghĩa là gì', 'Lộ giới là ranh giới dự kiến mở rộng đường theo quy hoạch. Phần nhà hoặc đất nằm trong lộ giới vẫn thuộc chủ sử dụng và vẫn giao dịch được, nhưng khi Nhà nước mở đường sẽ bị thu hồi phần đó, và khi xây mới thường không được xây kiên cố trên phần dính lộ giới. Giá trị phần đất dính lộ giới vì vậy thường thấp hơn phần còn lại. Nên xem bản đồ quy hoạch trước khi mua.', 'Lộ giới là ranh giới dự kiến mở rộng đường theo quy hoạch. Phần nhà hoặc đất nằm trong lộ giới vẫn thuộc chủ sử dụng và vẫn giao dịch được, nhưng khi Nhà nước mở đường sẽ bị thu hồi phần đó, và khi xây mới thường không được xây kiên cố trên phần dính lộ giới. Giá trị phần đất dính lộ giới vì vậy thường thấp hơn phần còn lại. Nên xem bản đồ quy hoạch trước khi mua.', 'Luật Quy hoạch đô thị và nông thôn 2024; Luật Xây dựng 2014 (sửa đổi 2020)', 'quy_hoach', '2026-10-25', 'chua', 13),
  ('thoi_han_sang_ten', 'Sang tên mất bao lâu, hạn đăng ký biến động là bao nhiêu ngày', 'Sau khi công chứng, hai bên phải đăng ký biến động (sang tên) trong 30 ngày kể từ ngày hợp đồng có hiệu lực; chậm có thể bị phạt hành chính. Cơ quan đăng ký giải quyết trong khoảng 10 ngày làm việc kể từ khi hồ sơ hợp lệ, thực tế tính cả bước nộp thuế thường mất 2 tới 3 tuần. Hồ sơ nộp tại Văn phòng đăng ký đất đai hoặc bộ phận một cửa của phường, xã.', 'Sau khi công chứng, hai bên phải đăng ký biến động (sang tên) trong 30 ngày kể từ ngày hợp đồng có hiệu lực; chậm có thể bị phạt hành chính. Cơ quan đăng ký giải quyết trong khoảng 10 ngày làm việc kể từ khi hồ sơ hợp lệ, thực tế tính cả bước nộp thuế thường mất 2 tới 3 tuần. Hồ sơ nộp tại Văn phòng đăng ký đất đai hoặc bộ phận một cửa của phường, xã.', 'Luật Đất đai 2024 (Điều 133); Nghị định 101/2024/NĐ-CP; Nghị định 123/2024/NĐ-CP về xử phạt', 'thu_tuc', '2026-10-25', 'chua', 14),
  ('nha_the_chap', 'Nhà đang thế chấp ngân hàng có mua bán được không', 'Được, nhưng phải có sự đồng ý của ngân hàng vì sổ đang do ngân hàng giữ. Cách phổ biến: bên mua chuyển một phần tiền để chủ nhà trả nợ, ngân hàng xoá thế chấp và trả sổ, rồi hai bên công chứng và sang tên; hoặc ký thoả thuận ba bên tại ngân hàng để tiền mua được dùng trả nợ trực tiếp. Nên làm việc tại ngân hàng và ghi rõ các bước trong hợp đồng đặt cọc.', 'Được, nhưng phải có sự đồng ý của ngân hàng vì sổ đang do ngân hàng giữ. Cách phổ biến: bên mua chuyển một phần tiền để chủ nhà trả nợ, ngân hàng xoá thế chấp và trả sổ, rồi hai bên công chứng và sang tên; hoặc ký thoả thuận ba bên tại ngân hàng để tiền mua được dùng trả nợ trực tiếp. Nên làm việc tại ngân hàng và ghi rõ các bước trong hợp đồng đặt cọc.', 'Bộ luật Dân sự 2015 (Điều 320, Điều 321); Luật Đất đai 2024', 'thu_tuc', '2026-10-25', 'chua', 15),
  ('tai_san_chung_vo_chong', 'Nhà chỉ một người đứng tên, bán có cần vợ hoặc chồng ký không', 'Nhà đất có được trong thời kỳ hôn nhân là tài sản chung của vợ chồng dù sổ chỉ ghi tên một người, nên khi bán cần cả hai đồng ý và ký, hoặc người kia có văn bản uỷ quyền, cam kết tài sản riêng được công chứng. Nếu mua trước khi kết hôn hoặc được thừa kế, tặng cho riêng thì là tài sản riêng, nhưng vẫn phải chứng minh bằng giấy tờ với công chứng viên.', 'Nhà đất có được trong thời kỳ hôn nhân là tài sản chung của vợ chồng dù sổ chỉ ghi tên một người, nên khi bán cần cả hai đồng ý và ký, hoặc người kia có văn bản uỷ quyền, cam kết tài sản riêng được công chứng. Nếu mua trước khi kết hôn hoặc được thừa kế, tặng cho riêng thì là tài sản riêng, nhưng vẫn phải chứng minh bằng giấy tờ với công chứng viên.', 'Luật Hôn nhân và gia đình 2014 (Điều 33, Điều 35, Điều 43)', 'giay_to', '2026-10-25', 'chua', 16),
  ('uy_quyen_ban', 'Mua bán nhà qua hợp đồng uỷ quyền có rủi ro gì', 'Hợp đồng uỷ quyền chỉ cho phép người được uỷ quyền thay mặt chủ làm thủ tục, không chuyển quyền sở hữu cho họ. Rủi ro: uỷ quyền chấm dứt khi người uỷ quyền chết hoặc đơn phương huỷ; cơ quan thuế có thể coi uỷ quyền toàn quyền là một lần chuyển nhượng và thu thêm thuế thu nhập cá nhân. Nếu bên bán không trực tiếp ký được, nên uỷ quyền có phạm vi rõ và thanh toán theo tiến độ sang tên.', 'Hợp đồng uỷ quyền chỉ cho phép người được uỷ quyền thay mặt chủ làm thủ tục, không chuyển quyền sở hữu cho họ. Rủi ro: uỷ quyền chấm dứt khi người uỷ quyền chết hoặc đơn phương huỷ; cơ quan thuế có thể coi uỷ quyền toàn quyền là một lần chuyển nhượng và thu thêm thuế thu nhập cá nhân. Nếu bên bán không trực tiếp ký được, nên uỷ quyền có phạm vi rõ và thanh toán theo tiến độ sang tên.', 'Bộ luật Dân sự 2015 (Điều 562 tới Điều 569); Thông tư 111/2013/TT-BTC (Điều 3 khoản 5)', 'giay_to', '2026-10-25', 'chua', 17),
  ('chung_cu_so_hong', 'Sổ hồng chung cư có thời hạn không, căn hộ chưa có sổ mua bán thế nào', 'Luật Nhà ở 2023 không quy định thời hạn sở hữu căn hộ; sổ hồng ghi thời hạn sử dụng đất của dự án (lâu dài hoặc theo thời hạn giao đất) và nhà chỉ phải kiểm định khi hết tuổi thọ công trình. Căn hộ chưa có sổ thì mua bán bằng cách chuyển nhượng hợp đồng mua bán với chủ đầu tư: công chứng văn bản chuyển nhượng, nộp thuế, rồi chủ đầu tư xác nhận; phải chưa nộp hồ sơ xin cấp sổ cho căn đó.', 'Luật Nhà ở 2023 không quy định thời hạn sở hữu căn hộ; sổ hồng ghi thời hạn sử dụng đất của dự án (lâu dài hoặc theo thời hạn giao đất) và nhà chỉ phải kiểm định khi hết tuổi thọ công trình. Căn hộ chưa có sổ thì mua bán bằng cách chuyển nhượng hợp đồng mua bán với chủ đầu tư: công chứng văn bản chuyển nhượng, nộp thuế, rồi chủ đầu tư xác nhận; phải chưa nộp hồ sơ xin cấp sổ cho căn đó.', 'Luật Nhà ở 2023 (Điều 58, Điều 160 tới Điều 162); Luật Kinh doanh bất động sản 2023', 'chung_cu', '2026-10-25', 'chua', 18),
  ('phi_bao_tri', 'Phí bảo trì 2% chung cư là gì, ai giữ', 'Người mua căn hộ nộp kinh phí bảo trì bằng 2% giá bán chưa gồm thuế giá trị gia tăng, thường nộp khi nhận bàn giao nhà. Khoản này chủ đầu tư phải gửi vào tài khoản riêng và bàn giao cho Ban quản trị khi toà nhà bầu được Ban quản trị, dùng để bảo trì phần sở hữu chung. Khác với phí quản lý vận hành đóng hằng tháng.', 'Người mua căn hộ nộp kinh phí bảo trì bằng 2% giá bán chưa gồm thuế giá trị gia tăng, thường nộp khi nhận bàn giao nhà. Khoản này chủ đầu tư phải gửi vào tài khoản riêng và bàn giao cho Ban quản trị khi toà nhà bầu được Ban quản trị, dùng để bảo trì phần sở hữu chung. Khác với phí quản lý vận hành đóng hằng tháng.', 'Luật Nhà ở 2023 (Điều 152 tới Điều 155)', 'chung_cu', '2026-10-25', 'chua', 19),
  ('nguoi_nuoc_ngoai', 'Người nước ngoài, Việt kiều có được mua nhà ở Việt Nam không', 'Người nước ngoài được phép nhập cảnh được mua căn hộ và nhà ở riêng lẻ trong dự án nhà ở thương mại (không thuộc khu vực cần bảo đảm quốc phòng, an ninh), tối đa 30% số căn hộ một toà, sở hữu tối đa 50 năm và có thể gia hạn; không được mua nhà ngoài dự án như nhà phố thông thường. Người Việt định cư ở nước ngoài còn quốc tịch Việt Nam có quyền như người trong nước theo Luật Đất đai 2024.', 'Người nước ngoài được phép nhập cảnh được mua căn hộ và nhà ở riêng lẻ trong dự án nhà ở thương mại (không thuộc khu vực cần bảo đảm quốc phòng, an ninh), tối đa 30% số căn hộ một toà, sở hữu tối đa 50 năm và có thể gia hạn; không được mua nhà ngoài dự án như nhà phố thông thường. Người Việt định cư ở nước ngoài còn quốc tịch Việt Nam có quyền như người trong nước theo Luật Đất đai 2024.', 'Luật Nhà ở 2023 (Điều 17 tới Điều 20); Luật Đất đai 2024 (Điều 4, Điều 44)', 'giay_to', '2026-10-25', 'chua', 20),
  ('hop_dong_thue', 'Hợp đồng thuê nhà có cần công chứng không, tiền cọc thuê, thuế cho thuê', 'Hợp đồng thuê nhà ở không bắt buộc công chứng, nhưng nên lập văn bản ghi rõ giá, thời hạn, cọc, điều kiện chấm dứt; muốn chắc hơn thì công chứng. Tiền cọc thuê do hai bên thoả thuận, phổ biến 1 tới 2 tháng tiền thuê. Chủ nhà có doanh thu cho thuê trên ngưỡng miễn thuế trong năm (ngưỡng theo Luật Thuế giá trị gia tăng 2024 là 200 triệu đồng/năm từ 2026) thì nộp thuế khoảng 10% doanh thu, gồm thuế giá trị gia tăng và thuế thu nhập cá nhân.', 'Hợp đồng thuê nhà ở không bắt buộc công chứng, nhưng nên lập văn bản ghi rõ giá, thời hạn, cọc, điều kiện chấm dứt; muốn chắc hơn thì công chứng. Tiền cọc thuê do hai bên thoả thuận, phổ biến 1 tới 2 tháng tiền thuê. Chủ nhà có doanh thu cho thuê trên ngưỡng miễn thuế trong năm (ngưỡng theo Luật Thuế giá trị gia tăng 2024 là 200 triệu đồng/năm từ 2026) thì nộp thuế khoảng 10% doanh thu, gồm thuế giá trị gia tăng và thuế thu nhập cá nhân.', 'Luật Nhà ở 2023 (Điều 164); Luật Thuế giá trị gia tăng 2024; Thông tư 40/2021/TT-BTC', 'cho_thue', '2026-10-25', 'chua', 21),
  ('giay_phep_xay_dung', 'Xây mới hoặc sửa nhà có cần giấy phép xây dựng không', 'Xây mới nhà ở riêng lẻ trong đô thị phải có giấy phép xây dựng, hồ sơ nộp tại UBND phường, xã (từ 01/07/2025 không còn cấp huyện). Sửa chữa không làm thay đổi kết cấu chịu lực, công năng, mặt ngoài tiếp giáp đường đô thị thì được miễn giấy phép. Nhà xây sai phép hoặc không phép có thể bị buộc tháo dỡ và khó hoàn công, nên kiểm giấy phép trước khi mua nhà mới xây.', 'Xây mới nhà ở riêng lẻ trong đô thị phải có giấy phép xây dựng, hồ sơ nộp tại UBND phường, xã (từ 01/07/2025 không còn cấp huyện). Sửa chữa không làm thay đổi kết cấu chịu lực, công năng, mặt ngoài tiếp giáp đường đô thị thì được miễn giấy phép. Nhà xây sai phép hoặc không phép có thể bị buộc tháo dỡ và khó hoàn công, nên kiểm giấy phép trước khi mua nhà mới xây.', 'Luật Xây dựng 2014 (sửa đổi 2020, Điều 89); Nghị quyết 190/2025/QH15 về sắp xếp chính quyền hai cấp', 'quy_hoach', '2026-10-25', 'chua', 22),
  ('len_tho_cu', 'Chuyển đất nông nghiệp, đất vườn lên đất thổ cư làm sao, tốn bao nhiêu', 'Phải nộp đơn xin chuyển mục đích sử dụng đất; chỉ được chấp thuận khi thửa đất phù hợp quy hoạch sử dụng đất là đất ở và còn chỉ tiêu. Khi được duyệt phải nộp tiền sử dụng đất bằng chênh lệch giữa giá đất ở và giá đất nông nghiệp theo bảng giá đất của tỉnh, thành; bảng giá mới từ 2025–2026 cao hơn trước nhiều nên khoản này có thể rất lớn. Nên hỏi UBND phường, xã về quy hoạch trước khi mua đất chờ lên thổ cư.', 'Phải nộp đơn xin chuyển mục đích sử dụng đất; chỉ được chấp thuận khi thửa đất phù hợp quy hoạch sử dụng đất là đất ở và còn chỉ tiêu. Khi được duyệt phải nộp tiền sử dụng đất bằng chênh lệch giữa giá đất ở và giá đất nông nghiệp theo bảng giá đất của tỉnh, thành; bảng giá mới từ 2025–2026 cao hơn trước nhiều nên khoản này có thể rất lớn. Nên hỏi UBND phường, xã về quy hoạch trước khi mua đất chờ lên thổ cư.', 'Luật Đất đai 2024 (Điều 121, Điều 122); Nghị định 103/2024/NĐ-CP về tiền sử dụng đất', 'quy_hoach', '2026-10-25', 'chua', 23),
  ('dat_nong_nghiep_mua', 'Mua đất nông nghiệp có xây nhà được không, ai được mua', 'Đất nông nghiệp chỉ được dùng đúng mục đích nông nghiệp, không được xây nhà ở; xây trái phép bị xử phạt và buộc tháo dỡ. Luật Đất đai 2024 cho phép cá nhân không trực tiếp sản xuất nông nghiệp nhận chuyển nhượng đất trồng lúa rộng hơn trước, nhưng có điều kiện về hạn mức và phương án sử dụng. Muốn ở thì phải xin chuyển mục đích lên đất ở và được chấp thuận.', 'Đất nông nghiệp chỉ được dùng đúng mục đích nông nghiệp, không được xây nhà ở; xây trái phép bị xử phạt và buộc tháo dỡ. Luật Đất đai 2024 cho phép cá nhân không trực tiếp sản xuất nông nghiệp nhận chuyển nhượng đất trồng lúa rộng hơn trước, nhưng có điều kiện về hạn mức và phương án sử dụng. Muốn ở thì phải xin chuyển mục đích lên đất ở và được chấp thuận.', 'Luật Đất đai 2024 (Điều 45, Điều 176, Điều 177)', 'quy_hoach', '2026-10-25', 'chua', 24)
